from pathlib import Path
import shutil
root=Path('E:/Git/ant')
base=root/'Assets/_Project/Scripts'
def edit(rel,old,new):
 p=base/rel
 s=p.read_text(encoding='utf-8-sig')
 assert old in s,rel+' missing '+old[:70]
 backup=root/'work/underground-before'/rel
 if not backup.exists():
  backup.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,backup)
 p.write_text(s.replace(old,new),encoding='utf-8-sig',newline='\r\n')
